package com.bank.resultshape;

import java.util.*;
import java.util.logging.*;

public class ShapeDemo {
    private static final Logger log = Logger.getLogger("Shape");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<String> names = List.of("Rajesh", "Priya", "Amit");
        ResultShapeService service = new ResultShapeService();

        List<String> asList = service.asList(names);
        String[] asArray = service.asArrayForLegacyApi(names);
        log.info(() -> "list  : " + asList);
        log.info(() -> "array : " + Arrays.toString(asArray));
    }
}

// ─── Would be in service/ResultShapeService.java ───
class ResultShapeService {
    // DEFAULT: List — flexible, generic-friendly, composable
    List<String> asList(List<String> names) {
        return names.stream().filter(n -> n.length() > 4)
            .collect(java.util.stream.Collectors.toList());
    }
    // ONLY when a legacy/varargs/array API requires it
    String[] asArrayForLegacyApi(List<String> names) {
        return names.stream().filter(n -> n.length() > 4)
            .toArray(String[]::new);
    }
}
